const payload = $('Execute Workflow Trigger').item.json || {};
const msg = payload.message || payload.body?.message || payload;
const rawText = String(msg?.text || payload.text || '').trim();
const chatId = msg?.chat?.id || payload.chatId || '';
function normalize(str) {
  return String(str || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
}
const text = normalize(rawText);
let action = 'help';
if (/ (xuat file|export file|chuyen file .* sang pdf|chuyen doc sang pdf|export sheet sang xlsx) /.test(text)) action = 'export_file';
else if (/ (share file|chia se file|cap quyen file|give access) /.test(text)) action = 'share_file';
else if (/ (xoa file|xoa thu muc|delete file|bo file vao thung rac|move file to trash) /.test(text)) action = 'delete_file';
else if (/ (di chuyen file|move file|chuyen file .* vao folder|dua file .* vao thu muc) /.test(text)) action = 'move_file';
else if (/ (doi ten file|rename file|doi ten thu muc|doi ten .* thanh .*) /.test(text)) action = 'rename_file';
else if (/ (copy file|nhan ban file|tao ban sao file|duplicate file|copy template) /.test(text)) action = 'copy_file';
else if (/ (download file|tai file|gui toi file|lay file|tai xuong file|send me file) /.test(text)) action = 'download_file';
else if (/ (upload file|luu file nay vao drive|luu tep nay vao drive|tai file nay len drive|up file) /.test(text)) action = 'upload_file';
else if (/ (tao folder|tao thu muc|create folder) /.test(text)) action = 'create_folder';
else if (/ (thong tin file|chi tiet file|file info|metadata file) /.test(text)) action = 'get_file_info';
else if (/ (tim file|search file|kiem file|tim trong drive|find file) /.test(text)) action = 'search_file';
else if (/ (xem drive|xem file drive|file gan day|liet ke file|danh sach file|list drive files|recent files) /.test(text)) action = 'list_files';
else if (/ (drive help|huong dan drive|dung drive nhu the nao|google drive help) /.test(text)) action = 'help';
else if (/ (drive|google drive) /.test(text)) action = 'list_files';
return [{ json: { payload, message: msg, chatId, rawText, text, action } }];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Drive').item.json;
const found = workflows.find((workflow) => workflow.name === source.workflowName);
if (!found) return [{ json: { ...source, hasWorkflow: false, response: 'Khong tim thay workflow con: ' + source.workflowName } }];
return [{ json: { ...source, hasWorkflow: true, workflowId: found.id } }];
